(150, 5000, 'MUSIC', 1, 'Hồ Chí Minh', '2026-05-24 14:00:00.000000', 'Đêm nhạc trữ tình quê hương quy tụ các giọng ca vàng bolero, mang đến không gian âm nhạc lắng đọng, ấm áp giữa lòng Sài Gòn nhộn nhịp.', '2026-07-15 22:30:00.000000', 'https://images.unsplash.com/photo-1487180142328-054b783fc471?q=80&w=1200&auto=format&fit=crop', b'1', '202 Hoàng Văn Thụ, Phường 9, Phú Nhuận', 1200000, 300000, 1, 'Bolero Harmony Club', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=200', 'Bolero Harmony', 'https://images.unsplash.com/photo-1487180142328-054b783fc471?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-07-15 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1487180142328-054b783fc471?q=80&w=400&auto=format&fit=crop', 'Đêm Nhạc Trữ Tình: Duyên Quê 2026', 5000, '2026-05-24 14:00:00.000000', 8900, 1),
(151, 1000, 'EXHIBITION', 2, 'Hà Nội', '2026-05-24 14:15:00.000000', 'Triển lãm trưng bày tác phẩm tranh đương đại của nhóm họa sĩ trẻ thủ đô, mang đến những góc nhìn mới mẻ về cuộc sống đô thị.', '2026-07-20 18:00:00.000000', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=1200&auto=format&fit=crop', b'0', 'Cổng số 1, Đại lộ Thăng Long, Mễ Trì', 500000, 100000, 1, 'Hanoi Fine Arts Club', 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=200', 'Fine Arts Hanoi', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-07-20 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=400&auto=format&fit=crop', 'Triển Lãm Mỹ Thuật Đương Đại Hà Nội', 1000, '2026-05-24 14:15:00.000000', 4300, 2),
(152, 3000, 'FESTIVAL', 3, 'Hồ Chí Minh', '2026-05-24 14:30:00.000000', 'Sự kiện lễ hội trình chiếu ánh sáng laser nghệ thuật đỉnh cao, mang lại không gian rực rỡ sắc màu cùng các ban nhạc indie nổi tiếng.', '2026-07-28 23:00:00.000000', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=1200&auto=format&fit=crop', b'1', '240-242 Đường 3/2, Phường 12, Quận 10', 800000, 200000, 1, 'Saigon Events Group', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=200', 'Saigon Events', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-07-28 19:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=400&auto=format&fit=crop', 'Lễ Hội Ánh Sáng Sài Gòn Night', 3000, '2026-05-24 14:30:00.000000', 12300, 3),
(153, 500, 'WORKSHOP', 4, 'Hà Nội', '2026-05-24 14:45:00.000000', 'Khoá học thực chiến thiết kế giao diện UI/UX nâng cao cùng các chuyên gia hàng đầu từ các tập đoàn công nghệ lớn tại Hà Nội.', '2026-08-05 17:30:00.000000', 'https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?q=80&w=1200&auto=format&fit=crop', b'0', 'Đường Lê Đức Thọ, Mỹ Đình, Nam Từ Liêm', 1500000, 500000, 1, 'Hanoi Tech Academy', 'https://images.unsplash.com/photo-1556761175-5973dc0f32d7?w=200', 'Hanoi Tech', 'https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-05 08:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?q=80&w=400&auto=format&fit=crop', 'Workshop: Kỹ Năng Thiết Kế Đồ Họa Cao Cấp', 500, '2026-05-24 14:45:00.000000', 3100, 4),
(154, 800, 'THEATER', 5, 'Hồ Chí Minh', '2026-05-24 15:00:00.000000', 'Vở kịch nói tình cảm gia đình đầy xúc động được chuyển thể từ tiểu thuyết kinh điển, do các diễn viên kỳ cựu miền Nam biểu diễn.', '2026-08-10 22:30:00.000000', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=1200&auto=format&fit=crop', b'0', '8 Nguyễn Bỉnh Khiêm, Đa Kao, Quận 1', 600000, 200000, 1, 'Sân Khấu Kịch Hồng Vân', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=200', 'Sân Khấu Hồng Vân', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-10 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=400&auto=format&fit=crop', 'Kịch Nói: Tiếng Chim Hót Trong Bụi Mận Gai', 800, '2026-05-24 15:00:00.000000', 5400, 5),
(155, 1500, 'SPORTS', 6, 'Hà Nội', '2026-05-24 15:15:00.000000', 'Giải đấu cầu lông quy tụ các tay vợt phong trào xuất sắc khu vực Hà Nội tranh tài giải thưởng hấp dẫn lên tới 50 triệu đồng.', '2026-08-12 18:00:00.000000', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?q=80&w=1200&auto=format&fit=crop', b'0', '12 Trịnh Hoài Đức, Cát Linh, Đống Đa', 300000, 100000, 1, 'Liên Đoàn Cầu Lông Hà Nội', 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?w=200', 'Cầu Lông HN', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-12 08:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?q=80&w=400&auto=format&fit=crop', 'Giải Vô Địch Cầu Lông Đống Đa 2026', 1500, '2026-05-24 15:15:00.000000', 2100, 6),
(156, 1200, 'COMEDY', 7, 'Đà Nẵng', '2026-05-24 15:30:00.000000', 'Đêm diễn hài độc thoại mang đậm phong cách văn hoá miền Trung với sự tham gia của các nghệ sĩ hài trẻ đang được yêu thích.', '2026-08-15 22:30:00.000000', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=1200&auto=format&fit=crop', b'0', 'Đường Trần Hưng Đạo, Quận Sơn Trà', 400000, 150000, 1, 'Comedy Central Danang', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?w=200', 'Comedy DN', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-15 20:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=400&auto=format&fit=crop', 'Hài Độc Thoại: Tiếng Cười Miền Trung', 1200, '2026-05-24 15:30:00.000000', 4600, 7),
(157, 1000, 'OTHER', 8, 'Đà Lạt', '2026-05-24 15:45:00.000000', 'Trải nghiệm ẩm thực rượu vang kết hợp không gian thưởng lãm hoa cẩm tú cầu lãng mạn giữa rừng thông Đà Lạt thơ mộng.', '2026-08-20 23:00:00.000000', 'https://images.unsplash.com/photo-1550136555-5f59c2efab22?q=80&w=1200&auto=format&fit=crop', b'1', 'Phường 1, Thành phố Đà Lạt', 700000, 300000, 1, 'Dalat Wine Club', 'https://images.unsplash.com/photo-1511192336575-5a79af67a629?w=200', 'Dalat Wine', 'https://images.unsplash.com/photo-1550136555-5f59c2efab22?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-20 18:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1550136555-5f59c2efab22?q=80&w=400&auto=format&fit=crop', 'Lễ Hội Rượu Vang & Hoa Đà Lạt', 1000, '2026-05-24 15:45:00.000000', 6700, 8),
(158, 6000, 'MUSIC', 1, 'Nha Trang', '2026-05-24 16:00:00.000000', 'Lễ hội âm nhạc EDM sôi động ngay trên bãi biển Nha Trang thơ mộng cùng các DJ quốc tế và hệ thống sân khấu ánh sáng cực đỉnh.', '2026-08-25 23:30:00.000000', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?q=80&w=1200&auto=format&fit=crop', b'1', 'Đại Lộ Nguyễn Tất Thành, Nha Trang', 1500000, 400000, 1, 'Nha Trang Beach Party Co.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=200', 'Nha Trang Party', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-25 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?q=80&w=400&auto=format&fit=crop', 'Nha Trang Beach EDM Festival 2026', 6000, '2026-05-24 16:00:00.000000', 14500, 9),
(159, 2000, 'EXHIBITION', 2, 'Cần Thơ', '2026-05-24 16:15:00.000000', 'Hội chợ trưng bày các công nghệ tự động hóa, robot thông minh phục vụ nông nghiệp hiện đại tại thành phố Cần Thơ.', '2026-08-30 18:00:00.000000', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?q=80&w=1200&auto=format&fit=crop', b'0', 'Lưu Hữu Phước, Ninh Kiều', 250000, 100000, 1, 'Mekong Tech Association', 'https://images.unsplash.com/photo-1536098561742-ca998e48cbcc?w=200', 'Mekong Tech', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-30 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?q=80&w=400&auto=format&fit=crop', 'Triển Lãm Nông Nghiệp Công Nghệ Cao Cần Thơ', 2000, '2026-05-24 16:15:00.000000', 2100, 10),
(160, 8000, 'FESTIVAL', 3, 'Hải Phòng', '2026-05-24 16:30:00.000000', 'Lễ hội thể thao bãi biển Đồ Sơn quy tụ các trò chơi lướt ván, bóng chuyền bãi biển kết hợp đại nhạc hội DJ cực nhiệt.', '2026-09-02 23:00:00.000000', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=1200&auto=format&fit=crop', b'1', '17 Lạch Tray, Ngô Quyền', 300000, 100000, 1, 'Hai Phong Sports Dept', 'https://images.unsplash.com/photo-1502224562085-639556652f33?w=200', 'HP Sports Dept', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-02 16:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=400&auto=format&fit=crop', 'Lễ Hội Thể Thao Biển Đồ Sơn', 8000, '2026-05-24 16:30:00.000000', 8900, 11),
(161, 300, 'WORKSHOP', 4, 'Hồ Chí Minh', '2026-05-24 16:45:00.000000', 'Workshop chia sẻ các phương pháp quản lý thời gian và năng suất làm việc tối ưu dành riêng cho các bạn lập trình viên phần mềm.', '2026-09-05 12:00:00.000000', 'https://images.unsplash.com/photo-1540317580384-e5d43867caa6?q=80&w=1200&auto=format&fit=crop', b'0', '202 Hoàng Văn Thụ, Phường 9, Phú Nhuận', 400000, 150000, 1, 'Saigon Coder Hub', 'https://images.unsplash.com/photo-1531538606174-0f90ff5dce83?w=200', 'Saigon Coder', 'https://images.unsplash.com/photo-1540317580384-e5d43867caa6?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-05 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1540317580384-e5d43867caa6?q=80&w=400&auto=format&fit=crop', 'Workshop: Quản Lý Thời Gian Cho Lập Trình Viên', 300, '2026-05-24 16:45:00.000000', 1200, 1),
(162, 1000, 'THEATER', 5, 'Hà Nội', '2026-05-24 17:00:00.000000', 'Tái hiện vở nhạc kịch hào hùng lịch sử dân tộc cải biên với sự kết hợp tuyệt vời giữa cải lương truyền thống và nhạc cụ phương Tây.', '2026-09-10 22:00:00.000000', 'https://images.unsplash.com/photo-1507676184212-d03ab07a01bf?q=80&w=1200&auto=format&fit=crop', b'1', 'Cổng số 1, Đại lộ Thăng Long, Mễ Trì', 1000000, 300000, 1, 'Hanoi Drama Club', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=200', 'Hanoi Drama', 'https://images.unsplash.com/photo-1507676184212-d03ab07a01bf?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-10 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1507676184212-d03ab07a01bf?q=80&w=400&auto=format&fit=crop', 'Nhạc Kịch: Tiếng Trống Mê Linh 2026', 1000, '2026-05-24 17:00:00.000000', 5600, 2),
(163, 2000, 'SPORTS', 6, 'Hồ Chí Minh', '2026-05-24 17:15:00.000000', 'Giải chạy bộ phong trào cự ly 10KM nâng cao sức khoẻ cộng đồng, tổ chức tại sân vận động Quân khu 7 với nhiều phần quà thú vị.', '2026-09-12 11:30:00.000000', 'https://images.unsplash.com/photo-1502224562085-639556652f33?q=80&w=1200&auto=format&fit=crop', b'0', '240-242 Đường 3/2, Phường 12, Quận 10', 400000, 200000, 1, 'Saigon Athletic Club', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=200', 'Saigon Athletic', 'https://images.unsplash.com/photo-1502224562085-639556652f33?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-12 06:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1502224562085-639556652f33?q=80&w=400&auto=format&fit=crop', 'Giải Marathon Bán Chuyên Hòa Bình', 2000, '2026-05-24 17:15:00.000000', 3200, 3),
(164, 1500, 'COMEDY', 7, 'Hà Nội', '2026-05-24 17:30:00.000000', 'Chương trình hài kịch trào phúng phản ánh đời sống thường nhật hóm hỉnh vui tươi, đem đến những tràng cười sảng khoái cuối tuần.', '2026-09-15 22:30:00.000000', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=1200&auto=format&fit=crop', b'0', 'Đường Lê Đức Thọ, Mỹ Đình, Nam Từ Liêm', 800000, 200000, 1, 'Hanoi Comedy Club', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?w=200', 'Hanoi Comedy', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-15 20:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=400&auto=format&fit=crop', 'Hài Kịch: Gặp Nhau Cuối Tuần 2026', 1500, '2026-05-24 17:30:00.000000', 7800, 4),
(165, 3000, 'OTHER', 8, 'Hồ Chí Minh', '2026-05-24 17:45:00.000000', 'Buổi trình diễn thời trang xuân hè cực kỳ lộng lẫy quy tụ các bộ thiết kế sáng tạo đột phá từ các nhà mốt danh tiếng hàng đầu.', '2026-09-20 22:30:00.000000', 'https://images.unsplash.com/photo-1485182708500-e8f1f318ba72?q=80&w=1200&auto=format&fit=crop', b'1', '8 Nguyễn Bỉnh Khiêm, Đa Kao, Quận 1', 2000000, 500000, 1, 'Vietnam Fashion Hub', 'https://images.unsplash.com/photo-1513151233558-d860c5398176?w=200', 'VN Fashion', 'https://images.unsplash.com/photo-1485182708500-e8f1f318ba72?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-20 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1485182708500-e8f1f318ba72?q=80&w=400&auto=format&fit=crop', 'Show Thời Trang: Sắc Xuân 2026', 3000, '2026-05-24 17:45:00.000000', 9200, 5),
(166, 1200, 'MUSIC', 1, 'Hà Nội', '2026-05-24 18:00:00.000000', 'Hòa nhạc giao hưởng mùa thu lắng đọng ấm áp tái hiện các tác phẩm giao hưởng lừng danh thế giới qua sự biểu diễn của dàn nhạc giao hưởng quốc gia.', '2026-09-25 22:30:00.000000', 'https://images.unsplash.com/photo-1511192336575-5a79af67a629?q=80&w=1200&auto=format&fit=crop', b'0', '12 Trịnh Hoài Đức, Cát Linh, Đống Đa', 1500000, 400000, 1, 'Vietnam Symphony Co.', 'https://images.unsplash.com/photo-1487180142328-054b783fc471?w=200', 'VNSO Co', 'https://images.unsplash.com/photo-1511192336575-5a79af67a629?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-25 20:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1511192336575-5a79af67a629?q=80&w=400&auto=format&fit=crop', 'Đêm Nhạc Giao Hưởng Mùa Thu', 1200, '2026-05-24 18:00:00.000000', 5100, 6),
