(185, 200, 'WORKSHOP', 4, 'Hồ Chí Minh', '2026-05-24 22:45:00.000000', 'Không gian trải nghiệm cắm hoa, làm gốm thủ công nghệ thuật kết hợp tiệc trà ấm cúng, thư thái giúp xua tan áp lực lo âu.', '2026-12-10 17:30:00.000000', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=1200&auto=format&fit=crop', b'0', '240-242 Đường 3/2, Phường 12, Quận 10', 800000, 300000, 1, 'Saigon Art & Tea Club', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?w=200', 'Art & Tea Club', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-10 14:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=400&auto=format&fit=crop', 'Workshop: Làm Gốm Thủ Công & Trà Chiều', 200, '2026-05-24 22:45:00.000000', 1200, 3),
(186, 1200, 'THEATER', 5, 'Hà Nội', '2026-05-24 23:00:00.000000', 'Vở diễn nhạc kịch Broadway kinh điển được dàn dựng chuyên nghiệp bởi các nghệ sĩ xuất sắc nhất Việt Nam và các nhạc công quốc tế.', '2026-12-12 22:30:00.000000', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=1200&auto=format&fit=crop', b'1', 'Đường Lê Đức Thọ, Mỹ Đình, Nam Từ Liêm', 3000000, 1000000, 1, 'Hanoi Symphony Orchestra', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=200', 'Hanoi Orchestra', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-12 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1460723237483-7a6dc9d0b212?q=80&w=400&auto=format&fit=crop', 'Nhạc Kịch: Phantom of the Opera (Hanoi)', 1200, '2026-05-24 23:00:00.000000', 6500, 4),
(187, 1000, 'SPORTS', 6, 'Hồ Chí Minh', '2026-05-24 23:15:00.000000', 'Các trận đấu Boxing tranh đai vô địch kịch tính nảy lửa quy tụ dàn võ sĩ hàng đầu khu vực Nam Bộ biểu diễn thi đấu.', '2026-12-15 22:00:00.000000', 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?q=80&w=1200&auto=format&fit=crop', b'0', '8 Nguyễn Bỉnh Khiêm, Đa Kao, Quận 1', 1000000, 300000, 1, 'Saigon Boxing League', 'https://images.unsplash.com/photo-1517649763962-0c623066013b?w=200', 'Saigon Boxing', 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-15 19:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1595435934249-5df7ed86e1c0?q=80&w=400&auto=format&fit=crop', 'Giải Đấu Boxing Tranh Đai Thần Tốc', 1000, '2026-05-24 23:15:00.000000', 4300, 5),
(188, 800, 'COMEDY', 7, 'Hà Nội', '2026-05-24 23:30:00.000000', 'Đêm diễn hài kịch độc thoại cực chất của cộng đồng hài miền Bắc mang lại vô số tiếng cười sáng tạo châm biếm thông minh.', '2026-12-18 22:30:00.000000', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=1200&auto=format&fit=crop', b'0', '12 Trịnh Hoài Đức, Cát Linh, Đống Đa', 400000, 150000, 1, 'Hanoi Comedy Group', 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?w=200', 'Hanoi Standup', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-18 20:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?q=80&w=400&auto=format&fit=crop', 'Hài Độc Thoại: Luyện Cười 2026', 800, '2026-05-24 23:30:00.000000', 2100, 6),
(189, 500, 'OTHER', 8, 'Đà Nẵng', '2026-05-24 23:45:00.000000', 'Buổi chia sẻ kiến thức đầu tư và quản lý tài sản tài chính cá nhân hiệu quả trong thời kỳ kinh tế nhiều biến động hiện nay.', '2026-12-20 12:00:00.000000', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=1200&auto=format&fit=crop', b'0', 'Đường Trần Hưng Đạo, Quận Sơn Trà', 800000, 300000, 1, 'Danang Finance Hub', 'https://images.unsplash.com/photo-1556761175-5973dc0f32d7?w=200', 'Danang Finance', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-20 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?q=80&w=400&auto=format&fit=crop', 'Hội Thảo Đầu Tư & Quản Lý Tài Sản', 500, '2026-05-24 23:45:00.000000', 1200, 7),
(190, 1500, 'MUSIC', 1, 'Đà Lạt', '2026-05-25 08:00:00.000000', 'Đại nhạc hội Acoustic trữ tình ngọt ngào lắng đọng trong không gian se lạnh đầy mộng mơ mây gió của thành phố Đà Lạt.', '2026-12-22 22:30:00.000000', 'https://images.unsplash.com/photo-1501281668745-f7f57925c3b4?q=80&w=1200&auto=format&fit=crop', b'1', 'Phường 1, Thành phố Đà Lạt', 1500000, 400000, 1, 'Dalat Acoustic Club', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=200', 'Dalat Acoustic', 'https://images.unsplash.com/photo-1501281668745-f7f57925c3b4?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-22 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1501281668745-f7f57925c3b4?q=80&w=400&auto=format&fit=crop', 'Đêm Nhạc Acoustic: Gió Và Mây Đà Lạt', 1500, '2026-05-25 08:00:00.000000', 9200, 8),
(191, 1200, 'EXHIBITION', 2, 'Nha Trang', '2026-05-25 08:15:00.000000', 'Triển lãm tương tác công nghệ 3D mapping khám phá thế giới sinh vật biển kỳ bí của đại dương bao la tại thành phố Nha Trang.', '2026-12-25 18:00:00.000000', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=1200&auto=format&fit=crop', b'0', 'Đại Lộ Nguyễn Tất Thành, Nha Trang', 400000, 150000, 1, 'Nha Trang Aquarium Center', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=200', 'Nha Trang Aquarium', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-25 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=400&auto=format&fit=crop', 'Triển Lãm Sinh Vật Biển & Công Nghệ', 1200, '2026-05-25 08:15:00.000000', 3100, 9),
(192, 5000, 'FESTIVAL', 3, 'Cần Thơ', '2026-05-25 08:30:00.000000', 'Lễ hội trái cây đặc sắc vùng miền với hàng trăm loại trái cây đặc sản miền Tây hấp dẫn và lễ hội diễu hành đường phố sôi nổi.', '2026-12-28 23:00:00.000000', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?q=80&w=1200&auto=format&fit=crop', b'1', 'Lưu Hữu Phước, Ninh Kiều', 200000, 50000, 1, 'Can Tho Tourism Office', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=200', 'Can Tho Tourism', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-28 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?q=80&w=400&auto=format&fit=crop', 'Lễ Hội Trái Cây Miền Tây Nam Bộ', 5000, '2026-05-25 08:30:00.000000', 7900, 10),
(193, 300, 'WORKSHOP', 4, 'Hải Phòng', '2026-05-25 08:45:00.000000', 'Buổi chia sẻ định hướng khởi nghiệp đột phá, áp dụng các công cụ trí tuệ nhân tạo (AI) giúp tăng tốc phát triển doanh nghiệp cho giới trẻ.', '2026-12-30 17:00:00.000000', 'https://images.unsplash.com/photo-1552581234-2612b75d8953?q=80&w=1200&auto=format&fit=crop', b'0', '17 Lạch Tray, Ngô Quyền', 500000, 200000, 1, 'Hai Phong Startup Association', 'https://images.unsplash.com/photo-1556761175-5973dc0f32d7?w=200', 'Hai Phong Startup', 'https://images.unsplash.com/photo-1552581234-2612b75d8953?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-12-30 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1552581234-2612b75d8953?q=80&w=400&auto=format&fit=crop', 'Workshop: Khởi Nghiệp Kỷ Nguyên AI', 300, '2026-05-25 08:45:00.000000', 1100, 11),
(194, 600, 'THEATER', 5, 'Hồ Chí Minh', '2026-05-25 09:00:00.000000', 'Vở kịch thể nghiệm nghệ thuật sân khấu vô cùng độc đáo thể hiện sâu sắc nội tâm nhân vật, được đông đảo giới chuyên môn đánh giá cao.', '2026-07-28 22:30:00.000000', 'https://images.unsplash.com/photo-1518020382113-a7e8fc38eac9?q=80&w=1200&auto=format&fit=crop', b'0', '202 Hoàng Văn Thụ, Phường 9, Phú Nhuận', 800000, 300000, 1, 'Saigon Art Drama Club', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=200', 'Saigon Art Drama', 'https://images.unsplash.com/photo-1518020382113-a7e8fc38eac9?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-07-28 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1518020382113-a7e8fc38eac9?q=80&w=400&auto=format&fit=crop', 'Kịch Thể Nghiệm: Dưới Cát Là Nước', 600, '2026-05-25 09:00:00.000000', 3200, 1),
(195, 3000, 'SPORTS', 6, 'Hà Nội', '2026-05-25 09:15:00.000000', 'Giải chạy bộ phong trào vì sức khỏe thanh niên thủ đô, chạy qua các tuyến phố tuyệt đẹp xung quanh trung tâm hội nghị quốc gia.', '2026-08-05 11:30:00.000000', 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?q=80&w=1200&auto=format&fit=crop', b'0', 'Cổng số 1, Đại lộ Thăng Long, Mễ Trì', 300000, 100000, 1, 'Hanoi Run Club', 'https://images.unsplash.com/photo-1502224562085-639556652f33?w=200', 'Hanoi Run', 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-05 06:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?q=80&w=400&auto=format&fit=crop', 'Giải Chạy Run For Youth 2026', 3000, '2026-05-25 09:15:00.000000', 4900, 2),
(196, 1200, 'COMEDY', 7, 'Hồ Chí Minh', '2026-05-25 09:30:00.000000', 'Đại hội hài kịch độc thoại cực chất từ các danh hài trẻ nổi tiếng Nam Bộ mang đến trọn vẹn những tiếng cười vui nhộn đầy ý nghĩa.', '2026-08-10 22:30:00.000000', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=1200&auto=format&fit=crop', b'0', '240-242 Đường 3/2, Phường 12, Quận 10', 500000, 200000, 1, 'Saigon Laugh Club', 'https://images.unsplash.com/photo-1527224857830-43a7ae858368?w=200', 'Saigon Laugh', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-10 20:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1585699324551-f6c309eedeca?q=80&w=400&auto=format&fit=crop', 'Stand-up Comedy: Cười Bể Bụng', 1200, '2026-05-25 09:30:00.000000', 6500, 3),
(197, 5000, 'OTHER', 8, 'Hà Nội', '2026-05-25 09:45:00.000000', 'Lễ hội ẩm thực quốc tế giao thoa giữa ẩm thực Á và Âu, cơ hội thưởng thức các món ăn độc đáo chế biến bởi các siêu đầu bếp quốc tế.', '2026-08-15 22:00:00.000000', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?q=80&w=1200&auto=format&fit=crop', b'1', 'Đường Lê Đức Thọ, Mỹ Đình, Nam Từ Liêm', 300000, 100000, 1, 'Hanoi Gastronomy League', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=200', 'Hanoi Gastronomy', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-12 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?q=80&w=400&auto=format&fit=crop', 'Festival Ẩm Thực Đường Phố Á-Âu', 5000, '2026-05-25 09:45:00.000000', 8900, 4),
(198, 4000, 'MUSIC', 1, 'Hồ Chí Minh', '2026-05-25 10:00:00.000000', 'Đêm nhạc rock bùng cháy hết mình từ các rock band gạo cội miền Nam mang đến ngọn lửa rock hoành tráng đầy đam mê.', '2026-08-20 23:30:00.000000', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?q=80&w=1200&auto=format&fit=crop', b'1', '8 Nguyễn Bỉnh Khiêm, Đa Kao, Quận 1', 1000000, 300000, 1, 'Saigon Rock Club', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=200', 'Saigon Rock', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-20 19:30:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?q=80&w=400&auto=format&fit=crop', 'Đêm Nhạc Rock: Lửa Sài Gòn', 4000, '2026-05-25 10:00:00.000000', 11300, 5),
(199, 1200, 'EXHIBITION', 2, 'Hà Nội', '2026-05-25 10:15:00.000000', 'Triển lãm nghệ thuật đồ họa và minh họa chuyên nghiệp của giới thiết kế Việt Nam quy tụ các tác phẩm ấn tượng, sáng tạo.', '2026-08-25 18:00:00.000000', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=1200&auto=format&fit=crop', b'0', '12 Trịnh Hoài Đức, Cát Linh, Đống Đa', 300000, 100000, 1, 'Vietnam Graphic Association', 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?w=200', 'VN Graphic', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-25 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?q=80&w=400&auto=format&fit=crop', 'Triển Lãm Đồ Họa & Minh Họa Việt Nam', 1200, '2026-05-25 10:15:00.000000', 2100, 6),
(200, 5000, 'FESTIVAL', 3, 'Đà Nẵng', '2026-05-25 10:30:00.000000', 'Lễ hội thả hoa đăng lung linh cầu chúc bình an bên bờ sông Hàn thơ mộng đầy thơ ca lãng mạn kết hợp trình chiếu nhạc nước.', '2026-08-30 23:00:00.000000', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=1200&auto=format&fit=crop', b'1', 'Đường Trần Hưng Đạo, Quận Sơn Trà', 300000, 100000, 1, 'Danang Festival Committee', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?w=200', 'Danang Fest', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-08-30 19:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1533174072545-7a4b6ad7a6c3?q=80&w=400&auto=format&fit=crop', 'Lễ Hội Thả Hoa Đăng Sông Hàn 2026', 5000, '2026-05-25 10:30:00.000000', 9200, 7),
(201, 200, 'WORKSHOP', 4, 'Đà Lạt', '2026-05-25 10:45:00.000000', 'Trải nghiệm buổi vẽ tranh màu nước thư thái thanh tịnh giữa không gian rừng thông lộng gió mộng mơ của xứ sở sương mù.', '2026-09-05 12:00:00.000000', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=1200&auto=format&fit=crop', b'0', 'Phường 1, Thành phố Đà Lạt', 600000, 250000, 1, 'Dalat Arts Hub', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?w=200', 'Dalat Arts', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=600&auto=format&fit=crop', '{"privacy":"public"}', '2026-09-05 09:00:00.000000', 'PUBLISHED', 'https://images.unsplash.com/photo-1526047932273-341f2a7631f9?q=80&w=400&auto=format&fit=crop', 'Workshop: Vẽ Tranh Màu Nước Giữa Rừng Thông', 200, '2026-05-25 10:45:00.000000', 1200, 8);
